<?php
declare(strict_types=1);
function agency_projects(int $limit=0,?array $selection=null): void {
 $items=$selection??array_values(array_filter(records('projects'),fn($p)=>meta('projects',(int)$p['id'])['published']??1));if($limit)$items=array_slice($items,0,$limit);
 echo '<div class="case-grid">';foreach($items as $p){$m=meta('projects',(int)$p['id']);$link='/projeler/'.$p['id'].'-'.slugify($p['name']);echo '<article class="case-card" data-project-category="'.e($p['category']).'"><a href="'.e($link).'" class="case-cover" aria-label="'.e($p['name']).' projesini inceleyin">';if(!empty($m['image_id']))echo media_image((int)$m['image_id']);else project_art($p['style']);echo '<span class="case-open" aria-hidden="true">↗</span></a><div class="case-info"><div><small>'.e($p['category']).'</small><h3><a href="'.e($link).'">'.e($p['name']).'</a></h3></div>'.($p['is_demo']?'<span class="concept-label">Konsept proje</span>':'').'</div><p>'.e($p['description']).'</p></article>'; }echo '</div>';
}
function agency_faq(int $service=0): void {
 $items=array_filter(cms_records('faqs'),fn($f)=>(int)$f['service_id']===$service);if(!$items)return;
 echo '<section class="agency-section faq-section"><div><span class="eyebrow">AKLINIZDAKİ SORULAR</span><h2>Biraz daha<br>netleştirelim.</h2><p>Projenize özel sorular için her zaman konuşabiliriz.</p></div><div class="faq-list">';foreach($items as $f)echo '<details><summary>'.e($f['question']).'<span>+</span></summary><p>'.nl2br(e($f['answer'])).'</p></details>';echo '</div></section>';
}
function agency_articles(int $limit=0,?array $selection=null): void {
 $items=$selection??($limit?growth_article_query([],$limit):published_articles());if($limit)$items=array_slice($items,0,$limit);if(!$items)return;
 echo '<div class="article-grid">';foreach($items as $a){echo '<article><a class="article-cover" href="/blog/'.e($a['slug']).'" aria-label="'.e($a['title']).'">';if($a['image_id'])echo media_image((int)$a['image_id']);else echo '<div class="article-art" aria-hidden="true"><span>ARKE<br>INSIGHTS.</span><i>↗</i></div>';echo '</a><div class="article-meta">'.e($a['category']).' <span>'.e(date('d.m.Y',strtotime($a['published_at']))).'</span></div><h3><a href="/blog/'.e($a['slug']).'">'.e($a['title']).'</a></h3><p>'.e($a['excerpt']).'</p><a class="text-link" href="/blog/'.e($a['slug']).'">Okumaya devam et ↗</a></article>'; }echo '</div>';
}
function agency_header(array $s): void { ?><div class="utility-bar"><span>Strateji, tasarım ve teknoloji. Aynı takımda.</span><div><?php if($s['email']): ?><a href="mailto:<?=e($s['email'])?>"><?=e($s['email'])?></a><?php endif; ?><span>TR <i>●</i></span></div></div><header class="agency-header"><a class="agency-logo" href="/" aria-label="<?=e($s['brand'])?> ana sayfa"><?php if((int)$s['logo_media']):echo media_image((int)$s['logo_media']);else: ?><?=brand_logo()?><?php endif; ?></a><nav class="agency-nav" aria-label="Ana menü"><?php foreach(cms_records('categories') as $c): ?><div class="nav-dropdown"><button class="mega-trigger" type="button" aria-expanded="false" aria-controls="mega-<?=$c['id']?>"><?=e($c['name'])?> <span>⌄</span></button><div class="mega-menu" id="mega-<?=$c['id']?>" hidden><div class="mega-intro"><small>UZMANLIK ALANLARIMIZ</small><h2><?=e($c['name'])?></h2><p><?=e($c['description'])?></p><a class="text-link" href="/uzmanlik/<?=e($c['slug'])?>">Tüm çözümler ↗</a></div><div class="mega-links"><?php foreach(category_services((int)$c['id']) as $service): ?><a href="/hizmetler/<?=e($service['slug'])?>"><strong><?=e($service['name'])?> <span>↗</span></strong><p><?=e($service['summary'])?></p></a><?php endforeach; ?></div></div></div><?php endforeach; ?><?php foreach(cms_records('navigation') as $n): ?><a href="<?=e($n['path']==='/iletisim'?growth_contact_url():$n['path'])?>"><?=e($n['label'])?></a><?php endforeach; ?></nav><a href="<?=e(growth_contact_url())?>" class="quote-button">Projenizi konuşalım <span>↗</span></a><button class="agency-menu-toggle" type="button" aria-controls="agency-mobile" aria-expanded="false" aria-label="Menüyü aç"><span></span><span></span></button></header><nav id="agency-mobile" class="agency-mobile" hidden aria-label="Mobil menü"><?php foreach(cms_records('categories') as $c): ?><details><summary><?=e($c['name'])?></summary><a href="/uzmanlik/<?=e($c['slug'])?>">Tüm <?=e($c['name'])?></a><?php foreach(category_services((int)$c['id']) as $service): ?><a href="/hizmetler/<?=e($service['slug'])?>"><?=e($service['name'])?></a><?php endforeach; ?></details><?php endforeach; foreach(cms_records('navigation') as $n): ?><a href="<?=e($n['path']==='/iletisim'?growth_contact_url():$n['path'])?>"><?=e($n['label'])?></a><?php endforeach; ?></nav><?php }
function service_directory(?array $category=null): void { ?><div class="service-directory"><?php $groups=$category?[$category]:cms_records('categories');foreach($groups as $c): ?><section class="service-family"><div class="family-title"><span>0<?=(int)$c['sort_order']?></span><h2><?=e($c['name'])?></h2><p><?=e($c['description'])?></p><a href="/uzmanlik/<?=e($c['slug'])?>">Alanı keşfet ↗</a></div><div class="family-services"><?php foreach(category_services((int)$c['id']) as $s): ?><a href="/hizmetler/<?=e($s['slug'])?>"><span class="service-symbol"><?=match((int)$c['id']){1=>'⌘',2=>'✳',default=>'↗'}?></span><div><h3><?=e($s['name'])?></h3><p><?=e($s['summary'])?></p></div><span class="family-arrow">↗</span></a><?php endforeach; ?></div></section><?php endforeach; ?></div><?php }
function agency_process(): void { ?><section class="agency-section work-process"><div class="section-title"><div><span class="eyebrow">BİRLİKTE NASIL İLERLİYORUZ?</span><h2>İyi bir sonuç,<br>iyi bir süreç ister.</h2></div><p>Açık iletişim. Net sorumluluklar.<br>Her aşamada birlikte verilen kararlar.</p></div><div class="work-steps"><?php foreach([['Keşif','İşinizi, hedef kitlenizi ve ihtiyaçlarınızı tanıyoruz.'],['Strateji','Öncelikleri, kapsamı ve yol haritasını belirliyoruz.'],['Üretim','Tasarımı ve teknolojiyi aynı hedef için geliştiriyoruz.'],['Yayın & gelişim','Kontrolleri tamamlıyor, sonraki adımları planlıyoruz.']] as $i=>$step): ?><article><span>0<?=$i+1?><i>↗</i></span><h3><?=$step[0]?></h3><p><?=$step[1]?></p></article><?php endforeach; ?></div></section><?php }
require_once __DIR__.'/home-v3.php';
require_once __DIR__.'/inner-pages.php';
function render_public(string $view,array $data=[]): void {
 $s=array_merge(cms_defaults(),settings());$title=$data['title']??$s['meta_title'];$description=$data['description']??$s['meta_description'];$extra=[];$entity='';$item=[];
 if($view==='service'){$entity='services';$item=$data['service'];}elseif($view==='landing'){$entity='pages';$item=$data['page'];}elseif($view==='article'){$entity='articles';$item=$data['article'];}elseif($view==='project'){$entity='projects';$item=$data['project'];}
 if($entity)$extra=meta($entity,(int)$item['id']);
 if(!empty($extra['seo_title']))$title=$extra['seo_title'];elseif($view!=='home'&&$view!=='landing')$title.=' | '.$s['brand'];
 if(!empty($extra['seo_description']))$description=$extra['seo_description'];
 $path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';$canonical=url(ltrim($path,'/'));if($view==='solutions'&&(int)($_GET['sayfa']??1)>1)$canonical.='?sayfa='.(int)$_GET['sayfa'];
 $noindex=!installed()||$s['site_noindex']==='1'||!empty($extra['noindex'])||($data['preview']??false)||in_array($view,['404','privacy'],true);
 if($noindex)header('X-Robots-Tag: noindex, follow');if($data['preview']??false)header('Cache-Control: no-store');
 $pageSeo=growth_page_seo($view,$s);if($pageSeo){$title=$pageSeo['title'];$description=$pageSeo['description'];}
 $GLOBALS['growthPageData']=$data;$GLOBALS['growthBreadcrumbs']=growth_breadcrumbs($view,$data);
 if(in_array($view,['blog','author'],true)&&(int)($_GET['sayfa']??1)>1){$canonical.='?sayfa='.(int)$_GET['sayfa'];$title.=' · Sayfa '.(int)$_GET['sayfa'];$description.=' Sayfa '.(int)$_GET['sayfa'].'.';}
 $noindex=$noindex||!empty($data['noindex']);if($noindex)header('X-Robots-Tag: noindex, follow');
 growth_cache_begin($view,array_replace($data,['noindex'=>$noindex]));
 $graph=growth_schema($view,$data,$s,$extra,$canonical,$description);
 $ogImage=media_url((int)(($pageSeo['image_id']??0)?:($extra['image_id']??0)?:($item['image_id']??0)?:$s['og_media']));

?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><meta name="description" content="<?=e($description)?>"><meta name="robots" content="<?=$noindex?'noindex,follow':'index,follow'?>"><link rel="canonical" href="<?=e($canonical)?>"><meta property="og:type" content="<?=$view==='article'?'article':'website'?>"><meta property="og:locale" content="tr_TR"><meta property="og:title" content="<?=e($title)?>"><meta property="og:description" content="<?=e($description)?>"><meta property="og:url" content="<?=e($canonical)?>"><?php if($ogImage): ?><meta property="og:image" content="<?=e(url($ogImage))?>"><?php endif; ?><meta name="twitter:card" content="summary_large_image"><?php if($s['search_console']): ?><meta name="google-site-verification" content="<?=e($s['search_console'])?>"><?php endif; ?><meta name="theme-color" content="#f7f8fa"><link rel="stylesheet" href="/assets/branding.css?v=2"><link rel="icon" href="/assets/arkesoft-logo-transparent.png"><?php growth_public_assets($view); ?><script type="application/ld+json"><?=json_encode(['@context'=>'https://schema.org','@graph'=>$graph],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP)?></script></head><body class="agency-site studio-site <?=$view==='home'?'studio-home':'studio-inner'?> page-<?=e($view)?> layout-<?=e(page_design($view)['layout']??'default')?>"><a href="#main" class="skip-link">İçeriğe geç</a><?php agency_header($s); ?><main id="main" tabindex="-1">
<?php if($data['preview']??false): ?><div class="preview-banner">Yönetici önizlemesi · Arama motorlarına kapalı</div><?php endif; ?>
<?php if($view==='home'):studio_home($s); ?>
<?php else: studio_inner($view,$data,$s,$extra); endif; ?>
<?php if(!in_array($view,['home','contact','privacy','404'],true)): ?><section class="agency-cta"><div><span class="eyebrow">BİR FİKİRDEN ÇOK DAHA FAZLASI.</span><h2><?=e($s['cta_title'])?></h2><a class="button light" href="<?=e(growth_contact_url())?>">Hadi konuşalım ↗</a></div><a href="<?=e(growth_contact_url())?>" class="cta-orbit" aria-label="İletişime geç">↗</a></section><?php endif; ?></main><footer class="agency-footer"><div class="footer-large"><a class="footer-wordmark" href="/" aria-label="ARKESOFT ana sayfa"><?=brand_logo(true)?></a><p><?=e($s['footer_note'])?></p></div><h2 class="sr-only">Diğer sayfalar ve iletişim</h2><div class="footer-columns"><div><span class="eyebrow">BİRLİKTE ÜRETELİM</span><?php if($s['email']): ?><a class="footer-email" href="mailto:<?=e($s['email'])?>"><?=e($s['email'])?></a><?php endif; ?><a href="<?=e(growth_contact_url())?>" class="text-link">Projenizi konuşalım ↗</a><div class="social-links"><?php foreach(['instagram','linkedin','youtube'] as $social):if(!$s[$social])continue; ?><a href="<?=e($s[$social])?>" target="_blank" rel="noopener"><?=ucfirst($social)?> ↗</a><?php endforeach; ?></div></div><?php foreach(cms_records('categories') as $c): ?><div><h3><?=e($c['name'])?></h3><?php foreach(category_services((int)$c['id']) as $service): ?><a href="/hizmetler/<?=e($service['slug'])?>"><?=e($service['name'])?></a><?php endforeach; ?></div><?php endforeach; ?></div><?php if($s['demo_content']==='1'): ?><p class="demo-disclosure">Konsept projeler ve örnek senaryolar içeren tanıtım sürümüdür.</p><?php endif; ?><div class="footer-bottom"><span>© <?=date('Y')?> <?=e($s['brand'])?>. Tüm hakları saklıdır.</span><div><a href="/ihtiyacini-belirle">İhtiyacınızı belirleyin</a><a href="/cozumler">Yerel çözümler</a><a href="/gizlilik">Gizlilik</a><a href="#main">Yukarı ↑</a></div></div></footer><?php growth_contact_bar(); ?></body></html><?php }
